// rtl/decoder.sv
//
// RV32IM instruction decoder. Maps a 32-bit instruction to control signals.
//
// Hard invariant (CLAUDE.md #2, #10):  is_illegal defaults to 1. It is
// cleared only inside arms that positively validate both opcode and the
// relevant funct fields (funct7 for R-type, funct3 for OP-IMM shifts,
// LOAD/STORE/BRANCH; full instruction match for SYSTEM/EBREAK).  Anything
// not explicitly recognised below traps via rvfi_trap.
//
// Convention (project-specific):
//   - EBREAK (0x00100073) is the *only* SYSTEM instruction marked legal.
//     ECALL, CSR ops, MRET all trap. EBREAK is the test-harness
//     termination marker; the architectural "should-trap" semantics are
//     intentionally relaxed here so selftest.S can halt without a CSR.
//   - FENCE / FENCE.I (opcode 0x0F) are architectural NOPs — legal but
//     reg_write=0, mem_*=0.
//
// Latency:        combinational (0 cycles).
// RVFI fields:    feeds rvfi_trap (= is_illegal at retirement), and all
//                 control routing into EX/MEM/WB.
module decoder (
  input  logic [31:0] instr,
  output logic [4:0]  alu_op,
  output logic        alu_src,
  output logic [2:0]  branch_op,
  output logic        is_branch,
  output logic        is_jump,
  output logic        is_jalr,
  output logic        is_lui,
  output logic        is_auipc,
  output logic        mem_read,
  output logic        mem_write,
  output logic [1:0]  mem_width,
  output logic        mem_sext,
  output logic        reg_write,
  output logic        mem_to_reg,
  output logic        is_illegal
);

  logic [6:0] opcode;
  logic [2:0] funct3;
  logic [6:0] funct7;

  always_comb begin
    opcode = instr[6:0];
    funct3 = instr[14:12];
    funct7 = instr[31:25];

    // Defaults — note is_illegal = 1.
    alu_op     = ALU_ADD;
    alu_src    = 1'b0;
    branch_op  = BR_BEQ;
    is_branch  = 1'b0;
    is_jump    = 1'b0;
    is_jalr    = 1'b0;
    is_lui     = 1'b0;
    is_auipc   = 1'b0;
    mem_read   = 1'b0;
    mem_write  = 1'b0;
    mem_width  = 2'd2;
    mem_sext   = 1'b1;
    reg_write  = 1'b0;
    mem_to_reg = 1'b0;
    is_illegal = 1'b1;

    case (opcode)
      // ── R-type OP ───────────────────────────────────────────────────────
      7'b0110011: begin
        // funct7=0x00: every funct3 is a base RV32I R-op (ADD/SLL/SLT/...).
        // funct7=0x20: only funct3=0 (SUB) or funct3=5 (SRA).
        // funct7=0x01: M-extension, every funct3 valid.
        if (funct7 == 7'b0000000 ||
            (funct7 == 7'b0100000 && (funct3 == 3'd0 || funct3 == 3'd5)) ||
            funct7 == 7'b0000001) begin
          is_illegal = 1'b0;
          reg_write  = 1'b1;
          case ({funct7, funct3})
            10'b0000000_000: alu_op = ALU_ADD;
            10'b0100000_000: alu_op = ALU_SUB;
            10'b0000000_001: alu_op = ALU_SLL;
            10'b0000000_010: alu_op = ALU_SLT;
            10'b0000000_011: alu_op = ALU_SLTU;
            10'b0000000_100: alu_op = ALU_XOR;
            10'b0000000_101: alu_op = ALU_SRL;
            10'b0100000_101: alu_op = ALU_SRA;
            10'b0000000_110: alu_op = ALU_OR;
            10'b0000000_111: alu_op = ALU_AND;
            10'b0000001_000: alu_op = ALU_MUL;
            10'b0000001_001: alu_op = ALU_MULH;
            10'b0000001_010: alu_op = ALU_MULHSU;
            10'b0000001_011: alu_op = ALU_MULHU;
            10'b0000001_100: alu_op = ALU_DIV;
            10'b0000001_101: alu_op = ALU_DIVU;
            10'b0000001_110: alu_op = ALU_REM;
            10'b0000001_111: alu_op = ALU_REMU;
            default:         alu_op = ALU_ADD;
          endcase
        end
      end

      // ── I-type OP-IMM ───────────────────────────────────────────────────
      7'b0010011: begin
        // Non-shift funct3 (0,2,3,4,6,7) — funct7 bits are part of imm,
        // accept them all.
        // Shift funct3 (1 SLLI, 5 SRLI/SRAI) — funct7 must be 0x00 (or 0x20
        // for SRAI only).
        if (funct3 != 3'd1 && funct3 != 3'd5) begin
          is_illegal = 1'b0;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
          case (funct3)
            3'd0:    alu_op = ALU_ADD;
            3'd2:    alu_op = ALU_SLT;
            3'd3:    alu_op = ALU_SLTU;
            3'd4:    alu_op = ALU_XOR;
            3'd6:    alu_op = ALU_OR;
            3'd7:    alu_op = ALU_AND;
            default: alu_op = ALU_ADD;
          endcase
        end else if (funct3 == 3'd1 && funct7 == 7'b0000000) begin // SLLI
          is_illegal = 1'b0;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
          alu_op     = ALU_SLL;
        end else if (funct3 == 3'd5 && funct7 == 7'b0000000) begin // SRLI
          is_illegal = 1'b0;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
          alu_op     = ALU_SRL;
        end else if (funct3 == 3'd5 && funct7 == 7'b0100000) begin // SRAI
          is_illegal = 1'b0;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
          alu_op     = ALU_SRA;
        end
      end

      // ── LOAD ────────────────────────────────────────────────────────────
      7'b0000011: begin
        // funct3 valid set: 0(LB), 1(LH), 2(LW), 4(LBU), 5(LHU). 3/6/7 reserved.
        if (funct3 == 3'd0 || funct3 == 3'd1 || funct3 == 3'd2 ||
            funct3 == 3'd4 || funct3 == 3'd5) begin
          is_illegal = 1'b0;
          mem_read   = 1'b1;
          mem_to_reg = 1'b1;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
          case (funct3)
            3'd0, 3'd4: mem_width = 2'd0;
            3'd1, 3'd5: mem_width = 2'd1;
            3'd2:       mem_width = 2'd2;
            default:    mem_width = 2'd2;
          endcase
          mem_sext = ~funct3[2];  // L*U have funct3[2]=1 -> sext=0
        end
      end

      // ── STORE ───────────────────────────────────────────────────────────
      7'b0100011: begin
        // funct3 valid set: 0(SB), 1(SH), 2(SW). 3..7 reserved.
        if (funct3 == 3'd0 || funct3 == 3'd1 || funct3 == 3'd2) begin
          is_illegal = 1'b0;
          mem_write  = 1'b1;
          alu_src    = 1'b1;
          case (funct3)
            3'd0:    mem_width = 2'd0;
            3'd1:    mem_width = 2'd1;
            3'd2:    mem_width = 2'd2;
            default: mem_width = 2'd2;
          endcase
        end
      end

      // ── BRANCH ──────────────────────────────────────────────────────────
      7'b1100011: begin
        // funct3 valid set: 0(BEQ), 1(BNE), 4(BLT), 5(BGE), 6(BLTU), 7(BGEU).
        // 2/3 reserved.
        if (funct3 != 3'd2 && funct3 != 3'd3) begin
          is_illegal = 1'b0;
          is_branch  = 1'b1;
          branch_op  = funct3;
        end
      end

      // ── JAL / JALR ──────────────────────────────────────────────────────
      7'b1101111: begin // JAL
        is_illegal = 1'b0;
        is_jump    = 1'b1;
        reg_write  = 1'b1;
      end
      7'b1100111: begin // JALR — funct3 must be 0
        if (funct3 == 3'd0) begin
          is_illegal = 1'b0;
          is_jump    = 1'b1;
          is_jalr    = 1'b1;
          reg_write  = 1'b1;
          alu_src    = 1'b1;
        end
      end

      // ── LUI / AUIPC ─────────────────────────────────────────────────────
      7'b0110111: begin // LUI
        is_illegal = 1'b0;
        is_lui     = 1'b1;
        reg_write  = 1'b1;
        alu_op     = ALU_LUI;
        alu_src    = 1'b1;
      end
      7'b0010111: begin // AUIPC
        is_illegal = 1'b0;
        is_auipc   = 1'b1;
        reg_write  = 1'b1;
        alu_src    = 1'b1;
      end

      // ── MISC-MEM (FENCE / FENCE.I) — architectural NOP ─────────────────
      7'b0001111: begin
        is_illegal = 1'b0;
      end

      // ── SYSTEM — only EBREAK accepted ───────────────────────────────────
      7'b1110011: begin
        if (instr == 32'h00100073) begin
          is_illegal = 1'b0;
        end
      end

      default: ; // is_illegal stays 1
    endcase
  end

endmodule


=== cores/bench/rtl/ex_stage.sv ===
// rtl/ex_stage.sv
//
// Execute stage. Resolves the operand muxes (forwarding from EX/MEM and
// MEM/WB), runs the ALU, resolves branches, computes the redirect
// target. Owns the EX/MEM pipeline register.
//
// Forwarding select encoding (driven by forward_unit):
//   00 = ID/EX register value (no forward)
//   01 = EX/MEM aluResult (instruction immediately ahead in MEM)
//   10 = MEM/WB result (instruction two ahead, post regfile-write mux)
//
// Latency:        1 cycle (EX/MEM register clocked here).
// RVFI fields:    feeds pc_wdata (= pc_next), the rd_wdata path for
//                 ALU and JAL/JALR (PC+4), and the branch resolve.
module ex_stage (
  input  logic               clock,
  input  logic               reset,
  input  logic               stall,         // freeze EX/MEM register (dmem stall)
  input  id_ex_t   in,
  input  logic [1:0]         fwd_rs1_sel,
  input  logic [1:0]         fwd_rs2_sel,
  input  logic [31:0]        fwd_ex_mem,    // EX/MEM.alu_result (registered)
  input  logic [31:0]        fwd_mem_wb,    // WB-stage write-data mux output
  output ex_mem_t  out,
  output logic               redirect,
  output logic [31:0]        redirect_target
);

  // ── Operand forwarding muxes ───────────────────────────────────────────
  logic [31:0] rs1;
  logic [31:0] rs2;

  always_comb begin
    case (fwd_rs1_sel)
      2'd1:    rs1 = fwd_ex_mem;
      2'd2:    rs1 = fwd_mem_wb;
      default: rs1 = in.rs1_val;
    endcase
    case (fwd_rs2_sel)
      2'd1:    rs2 = fwd_ex_mem;
      2'd2:    rs2 = fwd_mem_wb;
      default: rs2 = in.rs2_val;
    endcase
  end

  // ── ALU operand selection ─────────────────────────────────────────────
  logic [31:0] alu_a;
  logic [31:0] alu_b;
  always_comb begin
    alu_a = in.ctrl.is_auipc ? in.pc  : rs1;
    alu_b = in.ctrl.alu_src  ? in.imm : rs2;
  end

  logic [31:0] alu_result;
  alu u_alu (
    .op  (in.ctrl.alu_op),
    .a   (alu_a),
    .b   (alu_b),
    .out (alu_result)
  );

  // ── Branch resolve ────────────────────────────────────────────────────
  logic        branch_cond;
  logic        branch_taken;
  logic [31:0] branch_target;
  logic [31:0] jump_target;
  /* verilator lint_off UNUSEDSIGNAL */
  logic [31:0] jalr_sum;  // bit 0 deliberately dropped per RV JALR spec
  /* verilator lint_on UNUSEDSIGNAL */

  always_comb begin
    case (in.ctrl.branch_op)
      BR_BEQ:  branch_cond = (rs1 == rs2);
      BR_BNE:  branch_cond = (rs1 != rs2);
      BR_BLT:  branch_cond = ($signed(rs1) <  $signed(rs2));
      BR_BGE:  branch_cond = ($signed(rs1) >= $signed(rs2));
      BR_BLTU: branch_cond = (rs1 <  rs2);
      BR_BGEU: branch_cond = (rs1 >= rs2);
      default: branch_cond = 1'b0;
    endcase
    branch_taken  = in.ctrl.is_branch && branch_cond;
    branch_target = in.pc + in.imm;
    // JALR clears bit 0 (RV spec); JAL uses imm directly.
    jalr_sum    = rs1 + in.imm;
    jump_target = in.ctrl.is_jalr ? {jalr_sum[31:1], 1'b0}
                                  : (in.pc + in.imm);
  end

  // ── Misaligned branch / jump target trap ──────────────────────────────
  // riscv-formal's spec demands rvfi_trap=1 when next_pc is misaligned
  // (without C extension that means [1:0] != 0). We trap the offending
  // instruction, suppress the redirect (PC stays linear), and clear
  // reg_write so JAL/JALR don't write the return address on trap.
  logic misalign_branch;
  logic misalign_jump;
  logic misalign_fault;
  ctrl_t ctrl_with_trap;

  always_comb begin
    misalign_branch = in.ctrl.is_branch && branch_taken
                      && (branch_target[1:0] != 2'b00);
    misalign_jump   = in.ctrl.is_jump && (jump_target[1:0] != 2'b00);
    misalign_fault  = misalign_branch || misalign_jump;

    ctrl_with_trap = in.ctrl;
    if (misalign_fault) begin
      ctrl_with_trap.is_illegal = 1'b1;
      ctrl_with_trap.reg_write  = 1'b0;
    end
  end

  assign redirect        = (branch_taken || in.ctrl.is_jump) && !misalign_fault;
  assign redirect_target = in.ctrl.is_jump ? jump_target : branch_target;

  // ── EX/MEM register ───────────────────────────────────────────────────
  ex_mem_t reg_q;

  always_ff @(posedge clock) begin
    if (reset) begin
      reg_q <= '0;
    end else if (stall) begin
      // dmem stall: hold the EX/MEM register so the in-flight LOAD/STORE
      // stays in MEM stage waiting on the bus.
      reg_q <= reg_q;
    end else begin
      reg_q.pc            <= in.pc;
      // For JAL/JALR, the rd_wdata is PC+4 (return address), not the ALU's
      // sum (which is the jump target). The MEM/WB register's read-data
      // mux only kicks in for LOADs, so we route PC+4 here.
      reg_q.alu_result    <= in.ctrl.is_jump ? (in.pc + 32'd4) : alu_result;
      reg_q.write_data    <= rs2;
      reg_q.rd            <= in.rd;
      reg_q.rs1_addr      <= in.rs1_addr;
      reg_q.rs2_addr      <= in.rs2_addr;
      reg_q.rs1_val       <= rs1;
      reg_q.rs2_val       <= rs2;
      // pc_next reverts to pc+4 on misalign trap so the pc_fwd checker
      // (asserting next retirement's pc_rdata == this pc_wdata) stays
      // consistent with the suppressed redirect.
      reg_q.pc_next       <= misalign_fault     ? (in.pc + 32'd4)
                            : in.ctrl.is_jump   ? jump_target
                            : branch_taken      ? branch_target
                                                : (in.pc + 32'd4);
      reg_q.branch_taken  <= branch_taken;
      reg_q.branch_target <= branch_target;
      reg_q.ctrl          <= ctrl_with_trap;
      reg_q.instr         <= in.instr;
      reg_q.valid         <= in.valid;
    end
  end

  assign out = reg_q;

endmodule


=== cores/bench/rtl/forward_unit.sv ===
// rtl/forward_unit.sv
//
// Operand forwarding. For each rs in the EX-stage's source list, picks
// where the freshest value lives:
//   00 (NONE)    : ID/EX register's rs?_val (= regfile read of one cycle ago)
//   01 (EX_MEM)  : the in-flight ALU result from the EX/MEM register
//   10 (MEM_WB)  : the WB-stage's regfile-write data
//
// Priority is EX/MEM > MEM/WB > none (younger writer wins, x0 always 0).
//
// Latency:        combinational.
// RVFI fields:    n/a — feeds rs1_rdata / rs2_rdata via EX-stage muxes.
module forward_unit (
  input  logic [4:0] id_ex_rs1,
  input  logic [4:0] id_ex_rs2,
  input  logic [4:0] ex_mem_rd,
  input  logic       ex_mem_w_en,
  input  logic [4:0] mem_wb_rd,
  input  logic       mem_wb_w_en,
  output logic [1:0] fwd_rs1,
  output logic [1:0] fwd_rs2
);

  // Yosys's Verilog frontend rejects SV-style `function … return …`,
  // so the per-rs selection is open-coded in two always_comb blocks.
  always_comb begin
    if      (ex_mem_w_en && ex_mem_rd != 5'b0 && ex_mem_rd == id_ex_rs1) fwd_rs1 = 2'd1;
    else if (mem_wb_w_en && mem_wb_rd != 5'b0 && mem_wb_rd == id_ex_rs1) fwd_rs1 = 2'd2;
    else                                                                  fwd_rs1 = 2'd0;
  end

  always_comb begin
    if      (ex_mem_w_en && ex_mem_rd != 5'b0 && ex_mem_rd == id_ex_rs2) fwd_rs2 = 2'd1;
    else if (mem_wb_w_en && mem_wb_rd != 5'b0 && mem_wb_rd == id_ex_rs2) fwd_rs2 = 2'd2;
    else                                                                  fwd_rs2 = 2'd0;
  end

endmodule


=== cores/bench/rtl/hazard_unit.sv ===
// rtl/hazard_unit.sv
//
// Front-end and pipeline interlocks for the in-order five-stage core. The
// instruction prefetch queue owns instruction-bus backpressure, so an
// instruction bus stall is no longer a pipeline-wide stall. Decode waits
// only for a queue head, a load-use bubble, or a backend data-bus stall.
//
// Latency:        combinational.
// RVFI fields:   n/a (governs validity of subsequent retirements).
module hazard_unit (
  input  logic       id_ex_mem_read,
  input  logic [4:0] id_ex_rd,
  input  logic       if_id_valid,
  input  logic [4:0] if_id_rs1,
  input  logic [4:0] if_id_rs2,
  input  logic       queue_empty,
  input  logic       redirect,
  input  logic       dmem_ready,
  input  logic       ex_mem_mem_op,
  output logic       stall_id,
  output logic       flush_id,
  output logic       stall_ex_mem,
  output logic       hold_mem_wb
);

  logic load_use_hazard;
  logic dmem_stall;

  always_comb begin
    load_use_hazard = id_ex_mem_read && if_id_valid
                   && (id_ex_rd == if_id_rs1 || id_ex_rd == if_id_rs2)
                   && (id_ex_rd != 5'b0);

    // dmem_ready is relevant only for an actual memory operation in EX/MEM.
    // While that operation waits, the backend remains frozen but the
    // prefetch queue is deliberately allowed to fill.
    dmem_stall = !dmem_ready && ex_mem_mem_op;

    // An empty queue must not cause ID/EX to recapture its previous
    // instruction. The empty case is handled as a front-end bubble below;
    // only a backend stall or load-use interlock holds ID/EX in place.
    stall_id = dmem_stall || load_use_hazard;

    // Load-use inserts one bubble, and redirect kills the wrong-path decode
    // payload. A dmem stall has priority over either bubble operation so the
    // in-flight backend state remains held until the memory request completes.
    flush_id = (queue_empty || load_use_hazard || redirect) && !dmem_stall;

    stall_ex_mem = dmem_stall;

    // Keep the previous MEM/WB result available for forwarding while a load
    // or store is held in EX/MEM, but suppress duplicate retirement/writeback.
    hold_mem_wb = dmem_stall;
  end

endmodule


=== cores/bench/rtl/id_stage.sv ===
// rtl/id_stage.sv
//
// Decode stage. Combinationally drives the regfile read ports and the
// ID/EX register's next-state from the IF/ID combinational bundle plus
// the regfile read data. The ID/EX register is owned by this module so
// the decoded view of instruction n is latched by end of cycle n+1.
//
// Latency:        1 cycle (ID/EX register clocked here).
// RVFI fields:    feeds rs1_addr, rs1_rdata, rs2_addr, rs2_rdata, insn,
//                 trap (via ctrl.is_illegal).
module id_stage (
  input  logic              clock,
  input  logic              reset,
  input  logic              stall,
  input  logic              flush,
  input  if_id_t  in,
  // regfile read interface
  output logic [4:0]        rs1_addr,
  output logic [4:0]        rs2_addr,
  input  logic [31:0]       rs1_data,
  input  logic [31:0]       rs2_data,
  // ID/EX register output
  output id_ex_t  out
);

  // ── Combinational decode ────────────────────────────────────────────────
  logic [4:0]  dec_alu_op;
  logic        dec_alu_src;
  logic [2:0]  dec_branch_op;
  logic        dec_is_branch;
  logic        dec_is_jump;
  logic        dec_is_jalr;
  logic        dec_is_lui;
  logic        dec_is_auipc;
  logic        dec_mem_read;
  logic        dec_mem_write;
  logic [1:0]  dec_mem_width;
  logic        dec_mem_sext;
  logic        dec_reg_write;
  logic        dec_mem_to_reg;
  logic        dec_is_illegal;

  decoder u_decoder (
    .instr      (in.instr),
    .alu_op     (dec_alu_op),
    .alu_src    (dec_alu_src),
    .branch_op  (dec_branch_op),
    .is_branch  (dec_is_branch),
    .is_jump    (dec_is_jump),
    .is_jalr    (dec_is_jalr),
    .is_lui     (dec_is_lui),
    .is_auipc   (dec_is_auipc),
    .mem_read   (dec_mem_read),
    .mem_write  (dec_mem_write),
    .mem_width  (dec_mem_width),
    .mem_sext   (dec_mem_sext),
    .reg_write  (dec_reg_write),
    .mem_to_reg (dec_mem_to_reg),
    .is_illegal (dec_is_illegal)
  );

  logic [31:0] imm;
  imm_gen u_imm (.instr(in.instr), .imm(imm));

  // Regfile read addresses come straight from the IF/ID instruction — these
  // are also wired to the hazard unit at top level for load-use detection.
  assign rs1_addr = in.instr[19:15];
  assign rs2_addr = in.instr[24:20];

  ctrl_t ctrl_decoded;
  always_comb begin
    ctrl_decoded.alu_op     = dec_alu_op;
    ctrl_decoded.alu_src    = dec_alu_src;
    ctrl_decoded.branch_op  = dec_branch_op;
    ctrl_decoded.is_branch  = dec_is_branch;
    ctrl_decoded.is_jump    = dec_is_jump;
    ctrl_decoded.is_jalr    = dec_is_jalr;
    ctrl_decoded.is_lui     = dec_is_lui;
    ctrl_decoded.is_auipc   = dec_is_auipc;
    ctrl_decoded.mem_read   = dec_mem_read;
    ctrl_decoded.mem_write  = dec_mem_write;
    ctrl_decoded.mem_width  = dec_mem_width;
    ctrl_decoded.mem_sext   = dec_mem_sext;
    ctrl_decoded.reg_write  = dec_reg_write;
    ctrl_decoded.mem_to_reg = dec_mem_to_reg;
    ctrl_decoded.is_illegal = dec_is_illegal;
  end

  // ── ID/EX register ──────────────────────────────────────────────────────
  id_ex_t reg_q;

  always_ff @(posedge clock) begin
    if (reset || flush) begin
      reg_q <= '0;
    end else if (!stall) begin
      reg_q.pc       <= in.pc;
      reg_q.rs1_val  <= rs1_data;
      reg_q.rs2_val  <= rs2_data;
      reg_q.imm      <= imm;
      reg_q.rd       <= in.instr[11:7];
      reg_q.rs1_addr <= in.instr[19:15];
      reg_q.rs2_addr <= in.instr[24:20];
      reg_q.ctrl     <= ctrl_decoded;
      reg_q.instr    <= in.instr;
      reg_q.valid    <= in.valid;
    end
  end

  assign out = reg_q;

endmodule


=== cores/bench/rtl/if_stage.sv ===
// rtl/if_stage.sv
//
// Two-entry decoupled instruction prefetch queue. The fetch PC advances
// whenever the instruction bus accepts a word, independently of whether the
// decode stage is currently able to consume the queue head. This lets
// instruction fetch make progress while the backend is stalled on a data
// access or a load-use interlock.
//
// The queue is kept compact (entries occupy slot 0, then slot 1), which makes
// the head/empty handshake unambiguous and permits a one-word-per-cycle
// drain/fill when the queue is full. A redirect is an atomic queue flush: the
// old path is discarded, fetch restarts at redirect_target, and a ready target
// access may be installed directly into slot 0 on that same clock edge.
//
// Latency:        queue storage is synchronous; the head is combinational.
// RVFI fields:   feeds pc_rdata and instr through the ID/EX/MEM/WB path.
module if_stage (
  input  logic              clock,
  input  logic              reset,
  input  logic              redirect,
  input  logic [31:0]       redirect_target,
  input  logic              imem_ready,
  input  logic              consume,
  output logic [31:0]       imem_addr,
  input  logic [31:0]       imem_data,
  output if_id_t             out,
  output logic              queue_empty
);

  localparam logic [31:0] RESET_PC = 32'h0000_0000;
  localparam logic [31:0] NOP      = 32'h0000_0013;

  logic [31:0] fetch_pc_q;
  logic [31:0] entry_pc_q [0:1];
  logic [31:0] entry_insn_q [0:1];
  logic [1:0]  count_q;

  logic pop;
  logic push;

  // During redirect, selecting the target here makes a zero-wait bus able to
  // return the first target instruction without an extra dead fetch.
  assign imem_addr   = redirect ? redirect_target : fetch_pc_q;
  assign queue_empty = (count_q == 2'd0);

  always_comb begin
    out.pc    = queue_empty ? 32'b0 : entry_pc_q[0];
    out.instr = queue_empty ? NOP : entry_insn_q[0];
    out.valid = !queue_empty;
  end

  always_comb begin
    // A pop is only meaningful when the queue has a head. Redirect wins over
    // all normal queue traffic, so old-path data can never be retained.
    pop  = consume && !queue_empty && !redirect;
    push = imem_ready && (redirect || (count_q < 2'd2) || pop);
  end

  always_ff @(posedge clock) begin
    if (reset) begin
      fetch_pc_q      <= RESET_PC;
      count_q         <= 2'd0;
      entry_pc_q[0]   <= 32'b0;
      entry_pc_q[1]   <= 32'b0;
      entry_insn_q[0] <= NOP;
      entry_insn_q[1] <= NOP;
    end else if (redirect) begin
      // Flush both entries and restart the independent fetch pointer. The
      // target data is valid only when the redirected bus transaction was
      // accepted; otherwise the target remains the next request address.
      fetch_pc_q      <= redirect_target + (imem_ready ? 32'd4 : 32'd0);
      entry_pc_q[1]   <= 32'b0;
      entry_insn_q[1] <= NOP;
      if (imem_ready) begin
        count_q        <= 2'd1;
        entry_pc_q[0]   <= redirect_target;
        entry_insn_q[0] <= imem_data;
      end else begin
        count_q        <= 2'd0;
        entry_pc_q[0]   <= 32'b0;
        entry_insn_q[0] <= NOP;
      end
    end else begin
      if (push)
        fetch_pc_q <= fetch_pc_q + 32'd4;

      case ({pop, push})
        2'b01: begin
          // Append the accepted word to the current compact queue.
          if (count_q == 2'd0) begin
            entry_pc_q[0]   <= fetch_pc_q;
            entry_insn_q[0] <= imem_data;
          end else begin
            entry_pc_q[1]   <= fetch_pc_q;
            entry_insn_q[1] <= imem_data;
          end
          count_q <= count_q + 2'd1;
        end

        2'b10: begin
          // Drain without a replacement. If both entries were occupied,
          // promote the younger entry to the head.
          if (count_q == 2'd2) begin
            entry_pc_q[0]   <= entry_pc_q[1];
            entry_insn_q[0] <= entry_insn_q[1];
          end else begin
            entry_pc_q[0]   <= 32'b0;
            entry_insn_q[0] <= NOP;
          end
          entry_pc_q[1]   <= 32'b0;
          entry_insn_q[1] <= NOP;
          count_q <= count_q - 2'd1;
        end

        2'b11: begin
          // Simultaneous drain/fill. A one-entry queue replaces its head;
          // a full queue shifts slot 1 down and fills slot 1.
          if (count_q == 2'd1) begin
            entry_pc_q[0]   <= fetch_pc_q;
            entry_insn_q[0] <= imem_data;
          end else begin
            entry_pc_q[0]   <= entry_pc_q[1];
            entry_insn_q[0] <= entry_insn_q[1];
            entry_pc_q[1]   <= fetch_pc_q;
            entry_insn_q[1] <= imem_data;
          end
          count_q <= count_q;
        end

        default: begin
          count_q <= count_q;
        end
      endcase
    end
  end

endmodule


=== cores/bench/rtl/imm_gen.sv ===
// rtl/imm_gen.sv
//
// RV32I immediate generator. Sign-extends I/S/B/J immediates, zero-fills
// the low bits of U immediates. Opcodes that don't carry an immediate
// (R-type, FENCE, etc.) emit 0.
//
// Latency:        combinational (0 cycles).
// RVFI fields:    feeds the EX-stage immediate path (rd_wdata for ADDI,
//                 mem_addr for LOAD/STORE, pc_wdata for branches/jumps).
module imm_gen (
  input  logic [31:0] instr,
  output logic [31:0] imm
);

  logic [6:0] opcode;

  always_comb begin
    opcode = instr[6:0];
    case (opcode)
      // I-type: LOAD, OP-IMM, JALR, SYSTEM.
      7'b0000011, 7'b0010011, 7'b1100111, 7'b1110011:
        imm = {{20{instr[31]}}, instr[31:20]};
      // S-type: STORE.
      7'b0100011:
        imm = {{20{instr[31]}}, instr[31:25], instr[11:7]};
      // B-type: BRANCH (bit 0 implicit zero).
      7'b1100011:
        imm = {{19{instr[31]}}, instr[31], instr[7],
               instr[30:25], instr[11:8], 1'b0};
      // U-type: LUI, AUIPC (low 12 bits zero).
      7'b0110111, 7'b0010111:
        imm = {instr[31:12], 12'b0};
      // J-type: JAL (bit 0 implicit zero).
      7'b1101111:
        imm = {{11{instr[31]}}, instr[31], instr[19:12],
               instr[20], instr[30:21], 1'b0};
      default:
        imm = 32'b0;
    endcase
  end

endmodule


=== cores/bench/rtl/mem_stage.sv ===
// rtl/mem_stage.sv
//
// Memory access stage. Drives the dmem read/write ports combinationally
// from the EX/MEM register, and sign/zero-extends the loaded data into
// the MEM/WB register.
//
// Byte-lane discipline:
//   - Write data is replicated across all four byte lanes; the
//     byte-mask (mem_wmask) selects the actual destination bytes.
//   - Load: shift the raw word right by `addr[1:0]*8`, then sign- or
//     zero-extend the low 8/16 bits per the LB/LBU/LH/LHU encoding.
//   - For RVFI ALIGNED_MEM, mem_addr is reported word-aligned and the
//     byte position is captured in mem_rmask / mem_wmask.
//
// Latency:        1 cycle (MEM/WB register clocked here).
// RVFI fields:    feeds mem_addr, mem_rmask, mem_wmask, mem_rdata,
//                 mem_wdata, plus rd_wdata via the loaded-data path.
module mem_stage (
  input  logic               clock,
  input  logic               reset,
  // hold_wb: dmem stall is in effect. MEM/WB's data fields are RETAINED
  // (so the previously-retired LOAD's `rd` / `read_data` / `ctrl.reg_write`
  // remain visible to forward_unit), but `valid` is cleared so:
  //   - rvfi_order doesn't increment for held cycles
  //   - wb_stage doesn't write the regfile twice
  // Zeroing the whole register would lose the LOAD's load_data, breaking
  // MEM/WB->EX forwarding for any dependent instruction that's also held
  // in ID/EX during the stall (e.g. a BNE that consumes a LOAD's result).
  input  logic               hold_wb,
  // ex_mem_t carries branch_taken / branch_target / pc_next / rs?_val
  // for downstream RVFI use; mem_stage only consumes a subset, so the
  // remaining fields look unused from this module's perspective.
  /* verilator lint_off UNUSEDSIGNAL */
  input  ex_mem_t  in,
  /* verilator lint_on UNUSEDSIGNAL */
  // dmem interface
  output logic [31:0]        dmem_addr,
  output logic [31:0]        dmem_wdata,
  input  logic [31:0]        dmem_rdata,
  output logic [3:0]         dmem_wen,
  output logic               dmem_ren,
  // MEM/WB register output
  output mem_wb_t  out
);

  logic [31:0] wdata_rep;
  logic [3:0]  byte_mask;
  logic [31:0] aligned_addr;
  // shifted[31:16] is dropped on byte/halfword loads; only [15:0] feeds
  // the sign/zero-extension mux.
  /* verilator lint_off UNUSEDSIGNAL */
  logic [31:0] shifted;
  /* verilator lint_on UNUSEDSIGNAL */
  logic [7:0]  byte_val;
  logic [15:0] hword_val;
  logic [31:0] load_data;

  // Misaligned mem-access trap. RV32I requires word-aligned LW/SW and
  // halfword-aligned LH/LHU/SH; byte ops are always aligned.
  // riscv-formal's RISCV_FORMAL_ALIGNED_MEM contract demands rvfi_trap=1
  // when the effective byte address is not aligned to the access width.
  // On trap, the dmem ports are gated off and ctrl propagates is_illegal.
  logic mem_misalign;
  logic mem_op;
  ctrl_t ctrl_with_trap;

  always_comb begin
    // Byte/halfword replication for stores.
    case (in.ctrl.mem_width)
      2'd0:    wdata_rep = {4{in.write_data[7:0]}};
      2'd1:    wdata_rep = {2{in.write_data[15:0]}};
      default: wdata_rep = in.write_data;
    endcase

    // Byte-lane mask shifted to addr[1:0] * 1.
    case (in.ctrl.mem_width)
      2'd0:    byte_mask = (4'b0001 << in.alu_result[1:0]);
      2'd1:    byte_mask = (4'b0011 << in.alu_result[1:0]);
      default: byte_mask = 4'b1111;
    endcase

    mem_op       = in.ctrl.mem_read || in.ctrl.mem_write;
    mem_misalign = mem_op && (
                     (in.ctrl.mem_width == 2'd2 && in.alu_result[1:0] != 2'b00) ||
                     (in.ctrl.mem_width == 2'd1 && in.alu_result[0]   != 1'b0)
                     // 2'd0 (byte) is never misaligned.
                   );

    ctrl_with_trap = in.ctrl;
    if (mem_misalign) begin
      ctrl_with_trap.is_illegal = 1'b1;
      ctrl_with_trap.reg_write  = 1'b0;
    end

    // Combinational dmem outputs — gated off on misalign.
    dmem_addr  = in.alu_result;
    dmem_wdata = wdata_rep;
    dmem_wen   = (in.ctrl.mem_write && !mem_misalign) ? byte_mask : 4'b0000;
    dmem_ren   = in.ctrl.mem_read  && !mem_misalign;

    // Load extraction: shift right then sign/zero-extend the low N bits.
    shifted   = dmem_rdata >> (in.alu_result[1:0] * 8);
    byte_val  = shifted[7:0];
    hword_val = shifted[15:0];
    case (in.ctrl.mem_width)
      2'd0:    load_data = in.ctrl.mem_sext
                         ? {{24{byte_val[7]}},  byte_val}
                         : {24'b0,              byte_val};
      2'd1:    load_data = in.ctrl.mem_sext
                         ? {{16{hword_val[15]}}, hword_val}
                         : {16'b0,               hword_val};
      default: load_data = dmem_rdata;
    endcase

    // RVFI ALIGNED_MEM expects word-aligned mem_addr; mem_addr=0 if no access.
    aligned_addr = (mem_op && !mem_misalign)
                 ? {in.alu_result[31:2], 2'b00}
                 : 32'b0;
  end

  // ── MEM/WB register ───────────────────────────────────────────────────
  mem_wb_t reg_q;

  always_ff @(posedge clock) begin
    if (reset) begin
      reg_q <= '0;
    end else if (hold_wb) begin
      // Clear valid (no double-retire / no double-regfile-write), but
      // KEEP every other field. Forwarding from MEM/WB to a stalled
      // dependent in ID/EX needs the held LOAD's rd/read_data/ctrl
      // alive for as many cycles as the dmem stall lasts.
      reg_q.valid <= 1'b0;
    end else begin
      reg_q.pc         <= in.pc;
      reg_q.alu_result <= in.alu_result;
      reg_q.read_data  <= load_data;
      reg_q.rd         <= in.rd;
      reg_q.rs1_addr   <= in.rs1_addr;
      reg_q.rs2_addr   <= in.rs2_addr;
      reg_q.rs1_val    <= in.rs1_val;
      reg_q.rs2_val    <= in.rs2_val;
      reg_q.pc_next    <= in.pc_next;
      reg_q.mem_addr   <= aligned_addr;
      reg_q.mem_rdata  <= dmem_rdata;
      reg_q.mem_wdata  <= wdata_rep;
      reg_q.mem_wmask  <= (in.ctrl.mem_write && !mem_misalign) ? byte_mask : 4'b0000;
      reg_q.mem_rmask  <= (in.ctrl.mem_read  && !mem_misalign) ? byte_mask : 4'b0000;
      reg_q.ctrl       <= ctrl_with_trap;
      reg_q.instr      <= in.instr;
      reg_q.valid      <= in.valid;
    end
  end

